CREATE TABLE naturalPreferenceMeta(version INTEGER PRIMARY KEY CHECK(version=1),schemaHash TEXT NOT NULL);
CREATE TABLE naturalPreferenceEntries(id TEXT PRIMARY KEY,scopeKey TEXT NOT NULL REFERENCES strategyScopes(scopeKey),topic TEXT NOT NULL,revision INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','undone','forgotten')),updatedAt TEXT NOT NULL,UNIQUE(scopeKey,topic));
CREATE TABLE naturalPreferenceRevisions(entryId TEXT NOT NULL REFERENCES naturalPreferenceEntries(id),revision INTEGER NOT NULL,parentRevision INTEGER NOT NULL,sourceProject TEXT NOT NULL,sourceSession TEXT NOT NULL,sourceMessage TEXT NOT NULL,sourceHash TEXT NOT NULL,quoteHash TEXT NOT NULL,createdAt TEXT NOT NULL,PRIMARY KEY(entryId,revision));
CREATE TABLE naturalPreferenceContent(entryId TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL,PRIMARY KEY(entryId,revision),FOREIGN KEY(entryId,revision) REFERENCES naturalPreferenceRevisions(entryId,revision));
CREATE TABLE naturalPreferenceChanges(id TEXT PRIMARY KEY,scopeKey TEXT NOT NULL,entryId TEXT NOT NULL,jobId TEXT NOT NULL DEFAULT '',sessionId TEXT NOT NULL,sourceMessage TEXT NOT NULL,beforeRevision INTEGER NOT NULL,afterRevision INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('save','replace','undo','forget')),createdAt TEXT NOT NULL,undoneBy TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX naturalPreferenceChanges_job ON naturalPreferenceChanges(jobId) WHERE jobId<>'';
CREATE TABLE naturalPreferenceSuppressions(sourceMessage TEXT NOT NULL,sourceHash TEXT NOT NULL,createdAt TEXT NOT NULL,PRIMARY KEY(sourceMessage,sourceHash));
CREATE TABLE naturalPreferenceDispatches(id TEXT PRIMARY KEY,jobId TEXT NOT NULL,projectId TEXT NOT NULL,startedAt TEXT NOT NULL,finishedAt TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'dispatched',usageJSON TEXT NOT NULL DEFAULT '{}');
CREATE TRIGGER naturalPreferenceRevisions_immutable BEFORE UPDATE ON naturalPreferenceRevisions BEGIN SELECT RAISE(ABORT,'immutable preference revision'); END;
CREATE TRIGGER naturalPreferenceRevisions_no_delete BEFORE DELETE ON naturalPreferenceRevisions BEGIN SELECT RAISE(ABORT,'immutable preference revision'); END;
CREATE TRIGGER naturalPreferenceChanges_immutable BEFORE UPDATE ON naturalPreferenceChanges WHEN NEW.id<>OLD.id OR NEW.scopeKey<>OLD.scopeKey OR NEW.entryId<>OLD.entryId OR NEW.jobId<>OLD.jobId OR NEW.sessionId<>OLD.sessionId OR NEW.sourceMessage<>OLD.sourceMessage OR NEW.beforeRevision<>OLD.beforeRevision OR NEW.afterRevision<>OLD.afterRevision OR NEW.kind<>OLD.kind OR NEW.createdAt<>OLD.createdAt OR (OLD.undoneBy<>'' AND NEW.undoneBy<>OLD.undoneBy) BEGIN SELECT RAISE(ABORT,'immutable preference change'); END;
CREATE TABLE naturalPreferenceConsent(scopeKey TEXT PRIMARY KEY,enabledAt TEXT NOT NULL);
CREATE TABLE naturalPreferenceNoticeAcks(changeId TEXT PRIMARY KEY REFERENCES naturalPreferenceChanges(id));
